  AwxCopy.response: '\u041e\u0442\u0432\u0435\u0442 AWX \u043d\u0435 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044f \u0438\u043b\u0438 \u043d\u0435\u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0435\u043d.',
  AwxCopy.budget: '\u041e\u0442\u0432\u0435\u0442 AWX \u043f\u0440\u0435\u0432\u044b\u0441\u0438\u043b \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u044b\u0439 \u043e\u0431\u044a\u0451\u043c.',
  AwxCopy.forbidden: '\u0423 \u044d\u0442\u043e\u0439 \u0443\u0447\u0451\u0442\u043d\u043e\u0439 \u0437\u0430\u043f\u0438\u0441\u0438 AWX \u043d\u0435\u0442 \u043f\u0440\u0430\u0432 \u043d\u0430 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435.',
  AwxCopy.unauthorized: 'AWX \u043e\u0442\u043a\u043b\u043e\u043d\u0438\u043b \u0443\u0447\u0451\u0442\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435. \u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u0451\u043d\u043d\u0443\u044e \u0441\u0441\u044b\u043b\u043a\u0443.',
  AwxCopy.needsAwxInput: '\u0428\u0430\u0431\u043b\u043e\u043d\u0443 \u043d\u0443\u0436\u043d\u044b \u0443\u0447\u0451\u0442\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435, inventory, \u043f\u0430\u0440\u043e\u043b\u0438 \u0438\u043b\u0438 \u043e\u0442\u0432\u0435\u0442\u044b \u043d\u0430 \u043e\u043f\u0440\u043e\u0441. \u041d\u0430\u0441\u0442\u0440\u043e\u0439\u0442\u0435 \u0438\u0445 \u0432 AWX; \u043a\u043b\u0438\u0435\u043d\u0442 \u043d\u0435 \u0431\u0443\u0434\u0435\u0442 \u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0442\u044c \u044d\u0442\u043e\u0442 \u0448\u0430\u0431\u043b\u043e\u043d.',
  AwxCopy.unsupportedPrompts: '\u0428\u0430\u0431\u043b\u043e\u043d \u043d\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u043f\u0435\u0440\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0447\u0430\u0441\u0442\u0438 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432. \u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u0435\u0433\u043e \u0432 AWX.',
  AwxCopy.unknown: '\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044c \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u044e AWX.',
  AwxCopy.retired: '\u042d\u0442\u043e \u043e\u043a\u043d\u043e \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435 \u043e\u0442\u043d\u043e\u0441\u0438\u0442\u0441\u044f \u043a \u0438\u0441\u0445\u043e\u0434\u043d\u043e\u043c\u0443 \u0440\u0430\u0437\u0431\u043b\u043e\u043a\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c\u0443 \u043f\u0440\u043e\u0444\u0438\u043b\u044e. \u041e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 AWX \u0437\u0430\u043d\u043e\u0432\u043e.',
  AwxCopy.cancelRead: '\u041e\u0442\u043c\u0435\u043d\u0438\u0442\u044c \u0447\u0442\u0435\u043d\u0438\u0435',
